USE vehicle_rental; CREATE OR REPLACE VIEW booking_payment_summary AS SELECT b.booking_id, b.customer_id, CONCAT(c.first_name, ' ', c.last_name) AS customer_name, b.vehicle_id, v.registration_number, b.start_date, b.end_date, b.booking_status, b.total_amount, COALESCE(SUM(CASE WHEN p.payment_status = 'paid' THEN p.amount ELSE 0 END), 0) AS amount_paid, b.total_amount - COALESCE(SUM(CASE WHEN p.payment_status = 'paid' THEN p.amount ELSE 0 END), 0) AS amount_due, CASE WHEN b.total_amount = 0 THEN 'not_required' WHEN COALESCE(SUM(CASE WHEN p.payment_status = 'paid' THEN p.amount ELSE 0 END), 0) = 0 THEN 'unpaid' WHEN COALESCE(SUM(CASE WHEN p.payment_status = 'paid' THEN p.amount ELSE 0 END), 0) < b.total_amount THEN 'partial' ELSE 'paid' END AS payment_status FROM bookings b JOIN customers c ON c.customer_id = b.customer_id JOIN vehicles v ON v.vehicle_id = b.vehicle_id LEFT JOIN payments p ON p.booking_id = b.booking_id GROUP BY b.booking_id, b.customer_id, c.first_name, c.last_name, b.vehicle_id, v.registration_number, b.start_date, b.end_date, b.booking_status, b.total_amount;
